function M(t){const n=new Date(t),a=new Date,e=n.getFullYear()-a.getFullYear(),o=n.getMonth()-a.getMonth(),i=n.getDate()-a.getDate();return Math.max(0,e*12+o+(i<0?-1:0))}function d(t,n,a,e){if(e<=0)return t;const o=a/12;if(o===0)return t+n*e;const i=Math.pow(1+o,e);return t*i+n*((i-1)/o)}function L(t,n,a,e){if(e<=0)return Math.max(0,n-t);const o=a/12;if(o===0)return Math.max(0,(n-t)/e);const i=Math.pow(1+o,e),r=t*i,s=n-r;return s<=0?0:s/((i-1)/o)}function p(t,n,a,e){if(t>=e)return 0;if(n<=0&&t<e&&a<=0)return 1/0;let o=0,i=1200;for(;o<i;){const r=Math.floor((o+i)/2);d(t,n,a,r)>=e?i=r:o=r+1}return o}function $(t,n,a){if(n<=0)return"on_track";const e=t/n;return e>=1.05&&a>=3?"ahead":e>=.95&&a>=-1?"on_track":e>=.75?"behind":"at_risk"}function S(t,n,a,e,o,i){const r=t.monthlyContribution,s=t.targetAmount,l=i?"high":"medium";if(t.currentAmount>=s)return{type:"reach_now",amount:r,title:"🎉 הגעת ליעד",message:`הקופה "${t.name}" הגיעה ליעד ${s.toLocaleString("he-IL")}₪. אפשר לעצור את ההפקדה החודשית של ${r.toLocaleString("he-IL")}₪ ולכוון אותה למטרה אחרת.`,confidence:l};if(o==="ahead"){const h=Math.max(0,r-e),c=Math.floor(h/50)*50;if(c>=50){const f=r-c;return{type:"free_up",amount:c,title:"✨ שחרור תזרים",message:`הקופה "${t.name}" מקדימה את התכנית. אפשר להוריד את ההפקדה החודשית מ-${r.toLocaleString("he-IL")}₪ ל-${f.toLocaleString("he-IL")}₪ ועדיין להגיע ליעד בזמן. זה משחרר ${c.toLocaleString("he-IL")}₪ בחודש לתזרים הפנוי שלך.`,confidence:l}}}if(o==="behind"||o==="at_risk"){const h=Math.max(0,e-r),c=Math.ceil(h/50)*50;if(r>0&&c<r*3){const m=r+c;return{type:"increase",amount:c,title:"⚠️ חסר בתקציב",message:`הקופה "${t.name}" בפיגור. כדי להגיע ליעד בזמן צריך להעלות את ההפקדה החודשית מ-${r.toLocaleString("he-IL")}₪ ל-${m.toLocaleString("he-IL")}₪ (תוספת של ${c.toLocaleString("he-IL")}₪ לחודש).`,confidence:l}}const f=t.expectedAnnualReturn,u=p(t.currentAmount,r,f,s);if(u>0&&u<600){const m=new Date;m.setMonth(m.getMonth()+u);const g=u-n;return{type:"extend_date",suggestedDate:m.toISOString().split("T")[0],title:"📅 דחיית יעד",message:`בקצב הנוכחי הקופה "${t.name}" לא תגיע ליעד בזמן. בהפקדה של ${r.toLocaleString("he-IL")}₪ לחודש, המטרה תושג בעוד ${u} חודשים (דחייה של ${g} חודשים). אפשר להוסיף לתזרים או לדחות את היעד.`,confidence:l}}return{type:"increase",amount:c,title:"⚠️ יעד בסיכון",message:`הקופה "${t.name}" בסיכון גבוה. צריך להגדיל את ההפקדה ב-${c.toLocaleString("he-IL")}₪ לחודש או לבחון מחדש את היעד יחד עם המתכנן הפיננסי שלך.`,confidence:"low"}}return{type:"on_track",title:"בדרך הנכונה",message:`הקופה "${t.name}" בקצב טוב להגיע ליעד ${s.toLocaleString("he-IL")}₪ בזמן. המשך כך.`,confidence:l}}function I(t){const n=M(t.targetDate),a=n/12,e=typeof t.actualAnnualReturn=="number",o=e?t.actualAnnualReturn:t.expectedAnnualReturn,i=d(t.currentAmount,t.monthlyContribution,o,n),r=L(t.currentAmount,t.targetAmount,o,n),s=p(t.currentAmount,t.monthlyContribution,o,t.targetAmount),l=new Date;s!==1/0&&l.setMonth(l.getMonth()+s);const h=l.toISOString().split("T")[0],c=n-s,f=t.targetAmount>0?Math.min(100,Math.round(t.currentAmount/t.targetAmount*100)):0,u=t.targetAmount-i,m=$(i,t.targetAmount,c),g=S(t,n,i,r,m,e);return{bucketId:t.id,monthsRemaining:n,yearsRemaining:a,progressPct:f,projectedFinalValue:i,gap:u,requiredMonthly:r,currentMonthly:t.monthlyContribution,status:m,projectedCompletionDate:h,monthsVsTarget:c,recommendation:g,effectiveAnnualReturn:o}}function y(t){return t.map(I)}function w(t){return y(t).filter(n=>n.recommendation.type==="free_up"&&n.recommendation.amount).reduce((n,a)=>n+(a.recommendation.amount||0),0)}function A(t){return y(t).filter(n=>n.recommendation.type==="increase"&&n.recommendation.amount).reduce((n,a)=>n+(a.recommendation.amount||0),0)}export{A as a,I as p,w as t};
